import{_ as e,c as r,o as t,ag as s}from"./chunks/framework.CQuhCYrb.js";const p=JSON.parse('{"title":"Research Datasets/Maritime Sensors","description":"","frontmatter":{"title":"Research Datasets/Maritime Sensors"},"headers":[],"relativePath":"research/research-datasets-maritime-sensors.md","filePath":"research/research-datasets-maritime-sensors.md","lastUpdated":null}'),i={name:"research/research-datasets-maritime-sensors.md"};function o(l,a,n,c,m,h){return t(),r("div",null,[...a[0]||(a[0]=[s('<h1 id="research-datasets-maritime-sensors" tabindex="-1">Research Datasets/Maritime Sensors <a class="header-anchor" href="#research-datasets-maritime-sensors" aria-label="Permalink to &quot;Research Datasets/Maritime Sensors&quot;">​</a></h1><h2 id="maritime-sensors-research-catalog" tabindex="-1">Maritime Sensors Research Catalog <a class="header-anchor" href="#maritime-sensors-research-catalog" aria-label="Permalink to &quot;Maritime Sensors Research Catalog&quot;">​</a></h2><h3 id="overview" tabindex="-1">Overview <a class="header-anchor" href="#overview" aria-label="Permalink to &quot;Overview&quot;">​</a></h3><p>This page serves as a community-driven catalog of accessible maritime sensors. It highlights sources available to researchers, hobbyists, and OSINT analysts who want to monitor maritime activity — from AIS to satellite imagery and coastal cameras.</p><h3 id="research-question" tabindex="-1">Research Question <a class="header-anchor" href="#research-question" aria-label="Permalink to &quot;Research Question&quot;">​</a></h3><p>**What maritime sensors (AIS, coastal radar, ELINT, satellite imagery, webcams, etc.) are currently accessible for open or commercial use?’’’</p><h3 id="deliverable" tabindex="-1">Deliverable <a class="header-anchor" href="#deliverable" aria-label="Permalink to &quot;Deliverable&quot;">​</a></h3><p>A living catalog listing: Sensor names and types Basic specifications (if available) Access methods (free, paid, restricted) Data format notes (AIS, imagery, video feeds, RF collection)</p><h3 id="sensor-sources-catalog" tabindex="-1">Sensor Sources Catalog <a class="header-anchor" href="#sensor-sources-catalog" aria-label="Permalink to &quot;Sensor Sources Catalog&quot;">​</a></h3><h3 id="ais-automatic-identification-system" tabindex="-1">AIS (Automatic Identification System) <a class="header-anchor" href="#ais-automatic-identification-system" aria-label="Permalink to &quot;AIS (Automatic Identification System)&quot;">​</a></h3><p>**MarineTraffic’’’ — <a href="https://www.marinetraffic.com/" target="_blank" rel="noreferrer">Open AIS vessel tracking</a> **Spire Global’’’ — Space-based AIS and RF monitoring (commercial access). **Hawkeye 360’’’ — Space-based RF detection, including AIS (commercial). **SeaVision’’’ — Program for vessel classification and AIS correlation (military/civil collaborations).</p><h3 id="satellite-imagery" tabindex="-1">Satellite Imagery <a class="header-anchor" href="#satellite-imagery" aria-label="Permalink to &quot;Satellite Imagery&quot;">​</a></h3><p>**Planet Labs’’’ — <a href="https://www.planet.com/" target="_blank" rel="noreferrer">High-frequency optical imagery</a> (commercial; some government-access programs). **Capella Space’’’ — Synthetic Aperture Radar (SAR) imaging (paid service). **Maxar Technologies’’’ — High-resolution earth observation imagery (paid/commercial).</p><h3 id="coastal-radar-and-optical-sensors" tabindex="-1">Coastal Radar and Optical Sensors <a class="header-anchor" href="#coastal-radar-and-optical-sensors" aria-label="Permalink to &quot;Coastal Radar and Optical Sensors&quot;">​</a></h3><p>Some U.S. and international ports run independent optical, LIDAR, and radar surveillance systems. Access depends heavily on jurisdiction and local regulations.</p><h3 id="public-webcams-coastal-maritime" tabindex="-1">Public Webcams (Coastal &amp; Maritime) <a class="header-anchor" href="#public-webcams-coastal-maritime" aria-label="Permalink to &quot;Public Webcams (Coastal &amp; Maritime)&quot;">​</a></h3><p>**EarthCam’’’ — <a href="https://www.earthcam.com/mapsearch/" target="_blank" rel="noreferrer">Global network of public webcams</a> **Surfline’’’ — <a href="https://www.surfline.com/surf-reports-forecasts-cams" target="_blank" rel="noreferrer">Live surf conditions and beach cameras</a> **CamStreamer’’’ — <a href="https://camstreamer.com/live/map" target="_blank" rel="noreferrer">Aggregated live cameras worldwide</a> **WorldCams Beaches’’’ — <a href="https://worldcams.tv/beaches/" target="_blank" rel="noreferrer">Global beach camera streams</a></p><p>Common maritime chokepoints with public camera coverage: Bosphorus Strait Strait of Gibraltar Singapore Strait</p><h3 id="other-useful-observations" tabindex="-1">Other Useful Observations <a class="header-anchor" href="#other-useful-observations" aria-label="Permalink to &quot;Other Useful Observations&quot;">​</a></h3><p>**Port Watch Communities’’’ — Social media groups posting photos and observations of port activity. **Commercial AIS Trackers’’’ — Public-facing trackers like MarineTraffic are ideal for standard vessel movements, but limited for stealthy operations. &#39;&#39;&#39;Advanced Detection’’’ — Some programs (e.g., SeaVision) support ship-to-ship transfer monitoring and spoofing detection, combining multiple data sources.</p><h3 id="notes" tabindex="-1">Notes <a class="header-anchor" href="#notes" aria-label="Permalink to &quot;Notes&quot;">​</a></h3><p>Satellite-based systems like Planet and Spire provide imagery or RF data but typically require paid access. Public webcams and basic AIS trackers are freely available and useful for initial monitoring. Access to coastal radar data is typically restricted outside of local public safety contexts. Integration of multiple sources (AIS + satellite + webcams) improves reliability.</p><h3 id="useful-links" tabindex="-1">Useful Links <a class="header-anchor" href="#useful-links" aria-label="Permalink to &quot;Useful Links&quot;">​</a></h3><p><a href="https://www.marinetraffic.com/" target="_blank" rel="noreferrer">MarineTraffic Vessel Tracking</a><a href="https://www.planet.com/" target="_blank" rel="noreferrer">Planet Labs Imagery</a><a href="https://www.capellaspace.com/" target="_blank" rel="noreferrer">Capella Space SAR Imagery</a><a href="https://www.maxar.com/" target="_blank" rel="noreferrer">Maxar Technologies</a><a href="https://www.earthcam.com/mapsearch/" target="_blank" rel="noreferrer">EarthCam Webcams</a><a href="https://www.surfline.com/surf-reports-forecasts-cams" target="_blank" rel="noreferrer">Surfline Cams</a><a href="https://camstreamer.com/live/map" target="_blank" rel="noreferrer">CamStreamer Live Cams</a><a href="https://worldcams.tv/beaches/" target="_blank" rel="noreferrer">WorldCams Beach Cameras</a></p><h3 id="contribution" tabindex="-1">Contribution <a class="header-anchor" href="#contribution" aria-label="Permalink to &quot;Contribution&quot;">​</a></h3><p>If you know of additional maritime sensors or open data sources: Please share: sensor name, basic specs, and link. Add whether access is free, restricted, or paid.</p>',26)])])}const f=e(i,[["render",o]]);export{p as __pageData,f as default};
